begin;
create extension if not exists pgtap with schema extensions;
select plan(9);
insert into auth.users(id) values('ba8b2af4-a8b5-4b31-9d13-578f15bba743');
insert into public.materials(id,name,manufacturer_name) values('ba8b2af4-a8b5-4b31-9d13-578f15bba744','画像履歴テスト専用資材','デモ株式会社');
insert into public.material_images(id,material_id,url) values('ba8b2af4-a8b5-4b31-9d13-578f15bba745','ba8b2af4-a8b5-4b31-9d13-578f15bba744','https://example.com/product.png');
select public.set_material_editor_grant('ba8b2af4-a8b5-4b31-9d13-578f15bba744','33333333-3333-4333-8333-333333333333','IMAGE-TEST-DOC','ba8b2af4-a8b5-4b31-9d13-578f15bba743');
select set_config('request.jwt.claims','{"sub":"33333333-3333-4333-8333-333333333333","role":"authenticated","app_metadata":{"account_type":"seller","seller_id":"33333333-3333-4333-8333-333333333333"}}',true);
set local role authenticated;
select lives_ok($$select public.save_material_page_version('ba8b2af4-a8b5-4b31-9d13-578f15bba744','{"description":"画像の公開原稿","mainComponents":"","mechanism":"","links":[],"images":[{"path":"legacy:ba8b2af4-a8b5-4b31-9d13-578f15bba745","alt":"製品画像"}],"usages":[],"timings":[],"certifications":[]}',true)$$,'existing image is retained in submitted version');
select is((select count(*)::integer from public.material_page_existing_images where image_id='ba8b2af4-a8b5-4b31-9d13-578f15bba745'),1,'version records existing image reference');
reset role;
select lives_ok($$select public.review_material_page_version((select id from public.material_page_versions where material_id='ba8b2af4-a8b5-4b31-9d13-578f15bba744' and status='pending'),'ba8b2af4-a8b5-4b31-9d13-578f15bba743',true,'内部確認メモ')$$,'operator publishes image version');
select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role anon;
select is((select count(*)::integer from public.material_page_versions where material_id='ba8b2af4-a8b5-4b31-9d13-578f15bba744'),0,'internal version metadata is private after publishing');
select is((select description from public.public_material_page_versions where material_id='ba8b2af4-a8b5-4b31-9d13-578f15bba744'),'画像の公開原稿','public projection contains reviewed content');
reset role;
select set_config('request.jwt.claims','{"sub":"33333333-3333-4333-8333-333333333333","role":"authenticated","app_metadata":{"account_type":"seller","seller_id":"33333333-3333-4333-8333-333333333333"}}',true);
set local role authenticated;
select lives_ok($$select public.save_material_page_version('ba8b2af4-a8b5-4b31-9d13-578f15bba744','{"description":"画像を外した原稿","mainComponents":"","mechanism":"","links":[],"images":[],"usages":[],"timings":[],"certifications":[]}',true)$$,'manufacturer proposes removing image');
select is((select is_current from public.material_images where id='ba8b2af4-a8b5-4b31-9d13-578f15bba745'),true,'image remains public before review');
reset role;
select public.review_material_page_version((select id from public.material_page_versions where material_id='ba8b2af4-a8b5-4b31-9d13-578f15bba744' and status='pending'),'ba8b2af4-a8b5-4b31-9d13-578f15bba743',true,'確認完了');
select is((select is_current from public.material_images where id='ba8b2af4-a8b5-4b31-9d13-578f15bba745'),false,'image hidden after review');
select is((select count(*)::integer from public.material_images where id='ba8b2af4-a8b5-4b31-9d13-578f15bba745'),1,'image source retained for history');
select * from finish();
rollback;
